import random, subprocess, tempfile
from pathlib import Path
SAMPLE_IN = '3\n2 hello world\n4 the world is great\n2 great news\n4\nhello\nworld\ngreat\npku\n'
SAMPLE_OUT = '1\n1 2\n2 3\nNOT FOUND\n'
CASES = ['3\n2 hello world\n4 the world is great\n2 great news\n4\nhello\nworld\ngreat\npku\n', '4\n5 w0 w2 w3 w1 w6\n1 w2\n2 w7 w2\n2 w7 w2\n5\nw3\nw0\nw4\nw2\nw5\n', '20\n5 w0 w4 w2 w1 w7\n1 w6\n4 w0 w1 w8 w5\n3 w6 w8 w5\n7 w0 w3 w6 w8 w4 w2 w7\n2 w5 w7\n5 w0 w6 w3 w2 w8\n3 w4 w6 w0\n3 w5 w0 w3\n2 w2 w6\n1 w5\n5 w5 w0 w1 w3 w7\n3 w4 w6 w2\n5 w1 w4 w6 w5 w7\n3 w5 w6 w1\n7 w2 w7 w5 w8 w3 w6 w1\n6 w7 w1 w8 w3 w2 w0\n5 w6 w5 w3 w1 w4\n1 w5\n3 w6 w5 w0\n5\nw8\nw1\nw5\nw7\nw2\n', '5\n7 w1 w3 w0 w4 w5 w2 w6\n5 w2 w0 w4 w6 w1\n2 w4 w3\n6 w6 w1 w4 w3 w5 w0\n6 w6 w3 w0 w5 w1 w2\n5\nmissing\nw3\nw6\nw0\nw4\n', '14\n8 w6 w1 w8 w9 w13 w14 w11 w12\n4 w14 w17 w13 w0\n8 w7 w11 w0 w16 w1 w17 w9 w2\n2 w12 w4\n1 w13\n6 w12 w7 w16 w6 w2 w1\n3 w0 w18 w5\n4 w1 w16 w7 w2\n4 w15 w17 w16 w3\n4 w10 w11 w9 w15\n3 w17 w9 w7\n3 w4 w8 w13\n8 w11 w5 w0 w12 w1 w9 w14 w2\n7 w16 w11 w10 w0 w4 w7 w3\n4\nw18\nw4\nw17\nw11\n', '6\n4 w5 w6 w3 w2\n4 w6 w4 w0 w7\n3 w7 w5 w3\n7 w3 w4 w1 w0 w6 w2 w5\n4 w5 w6 w0 w3\n6 w3 w6 w0 w2 w1 w4\n8\nw1\nw6\nw4\nw7\nw0\nw2\nw5\nmissing\n', '2\n2 w8 w7\n4 w0 w8 w5 w2\n3\nw3\nw4\nw1\n', '7\n2 w1 w3\n2 w3 w2\n2 w2 w0\n2 w4 w3\n1 w4\n5 w0 w4 w1 w2 w3\n1 w1\n4\nw4\nw0\nw3\nw1\n', '12\n1 w4\n4 w9 w10 w6 w15\n6 w13 w11 w0 w3 w5 w9\n5 w10 w9 w4 w6 w0\n6 w4 w7 w1 w8 w12 w5\n2 w3 w5\n1 w3\n6 w12 w9 w2 w11 w7 w4\n3 w4 w10 w5\n1 w0\n8 w0 w13 w3 w11 w4 w1 w2 w14\n6 w0 w10 w8 w14 w5 w15\n9\nw10\nmissing\nw4\nw1\nw9\nw6\nw5\nw12\nw14\n', '20\n3 w6 w4 w7\n3 w6 w7 w8\n6 w7 w4 w2 w6 w1 w0\n3 w7 w1 w8\n5 w4 w3 w0 w2 w1\n7 w2 w4 w6 w3 w7 w5 w0\n3 w5 w0 w8\n7 w0 w6 w4 w3 w2 w1 w8\n4 w2 w6 w3 w7\n3 w0 w5 w4\n6 w7 w4 w8 w6 w5 w3\n8 w5 w3 w8 w4 w2 w0 w1 w7\n2 w6 w4\n7 w6 w1 w2 w4 w3 w5 w8\n8 w6 w2 w1 w5 w7 w8 w0 w3\n7 w0 w1 w7 w6 w3 w4 w5\n8 w6 w4 w5 w8 w3 w0 w1 w2\n1 w3\n5 w2 w6 w0 w3 w5\n2 w6 w2\n8\nw0\nw3\nw4\nw1\nw5\nw2\nw8\nw6\n', '8\n5 w3 w0 w4 w1 w2\n3 w2 w4 w0\n5 w4 w2 w3 w0 w1\n4 w3 w2 w1 w0\n3 w0 w1 w4\n4 w2 w0 w3 w4\n4 w0 w3 w1 w2\n5 w1 w2 w0 w3 w4\n5\nw2\nw0\nw4\nw1\nw3\n', '4\n3 w2 w6 w7\n8 w4 w2 w6 w8 w12 w10 w3 w14\n3 w9 w15 w10\n2 w13 w14\n6\nw2\nw9\nw15\nw4\nw7\nw13\n', '4\n2 w6 w0\n3 w0 w6 w2\n6 w0 w6 w1 w2 w3 w5\n2 w0 w4\n3\nw4\nw2\nw1\n', '17\n7 w6 w4 w1 w12 w10 w0 w2\n6 w7 w13 w6 w3 w0 w10\n8 w0 w1 w13 w5 w2 w7 w12 w9\n2 w12 w1\n2 w3 w7\n2 w13 w0\n3 w9 w12 w6\n3 w7 w8 w3\n5 w5 w7 w6 w9 w13\n1 w7\n3 w2 w3 w12\n3 w9 w6 w10\n6 w11 w4 w13 w9 w5 w2\n7 w8 w1 w12 w4 w13 w3 w0\n7 w8 w3 w5 w7 w10 w0 w9\n8 w2 w13 w0 w12 w10 w5 w11 w7\n4 w5 w3 w6 w12\n6\nw5\nw8\nw10\nw1\nw7\nw0\n', '13\n3 w3 w1 w4\n4 w5 w0 w4 w1\n1 w2\n3 w0 w4 w5\n5 w2 w4 w3 w0 w1\n3 w4 w1 w5\n6 w1 w5 w4 w0 w3 w2\n3 w1 w2 w3\n1 w0\n1 w5\n2 w5 w4\n3 w4 w1 w0\n2 w2 w0\n3\nw0\nw4\nw1\n', '18\n3 w4 w1 w0\n3 w2 w5 w4\n5 w1 w3 w2 w5 w0\n5 w2 w3 w0 w1 w4\n5 w2 w0 w3 w5 w1\n6 w1 w0 w5 w3 w2 w4\n6 w5 w1 w4 w3 w2 w0\n3 w5 w2 w0\n3 w1 w2 w4\n4 w0 w1 w3 w4\n3 w2 w1 w5\n6 w5 w0 w2 w3 w4 w1\n2 w1 w0\n6 w2 w5 w1 w3 w0 w4\n6 w5 w3 w2 w1 w4 w0\n3 w0 w1 w2\n2 w3 w2\n3 w1 w2 w3\n5\nmissing\nw2\nw3\nw5\nw4\n', '13\n1 w0\n3 w3 w6 w1\n2 w5 w0\n7 w4 w8 w2 w7 w1 w9 w5\n2 w5 w2\n6 w8 w4 w3 w2 w1 w5\n4 w6 w0 w1 w7\n7 w9 w7 w2 w5 w3 w4 w8\n2 w2 w0\n2 w1 w7\n2 w0 w4\n2 w4 w3\n6 w5 w2 w4 w7 w8 w6\n6\nw5\nw4\nw0\nw1\nmissing\nw9\n', '2\n2 w3 w7\n5 w11 w13 w8 w6 w12\n3\nw2\nw11\nw8\n', '13\n8 w6 w7 w2 w0 w5 w4 w3 w1\n3 w2 w7 w1\n3 w6 w0 w4\n7 w4 w2 w7 w5 w0 w6 w3\n2 w7 w4\n1 w7\n2 w7 w4\n8 w7 w4 w2 w6 w3 w5 w0 w1\n8 w7 w2 w5 w4 w1 w3 w6 w0\n1 w2\n6 w0 w2 w5 w3 w4 w7\n1 w6\n4 w4 w3 w1 w7\n7\nw0\nw3\nw5\nw1\nw6\nmissing\nw7\n', '7\n3 w13 w11 w9\n5 w9 w7 w2 w8 w1\n1 w11\n3 w7 w13 w6\n7 w0 w3 w12 w5 w1 w8 w7\n7 w10 w3 w5 w9 w2 w1 w12\n8 w13 w9 w4 w7 w8 w5 w6 w1\n3\nw10\nw5\nw6\n']
REFERENCE_SOURCE = 'from collections import defaultdict\ndef main():\n    n = int(input())\n    index = 1\n    inverted_index = defaultdict(set)   # 构建倒排索引\n    for i in range(1, n + 1):\n        parts = input().split()\n        doc_id = i\n        num_words = int(parts[0])\n        words = parts[1:num_words + 1]\n        for word in words:\n            inverted_index[word].add(doc_id)\n\n    m = int(input())\n    results = []\n\n    # 查询倒排索引\n    for _ in range(m):\n        query = input()\n        if query in inverted_index:\n            results.append(" ".join(map(str, sorted(list(inverted_index[query])))))\n        else:\n            results.append("NOT FOUND")\n\n    # 输出查询结果\n    for result in results:\n        print(result)\n\nif __name__ == "__main__":\n    main()\n'
assert CASES[0] == SAMPLE_IN
random.seed(6640)
def solve_reference(content):
    with tempfile.NamedTemporaryFile("w", suffix=".py", encoding="utf-8") as handle:
        handle.write(REFERENCE_SOURCE); handle.flush()
        result = subprocess.run(["python3", handle.name], input=content, text=True, capture_output=True, timeout=5, check=True)
    return result.stdout
assert solve_reference(SAMPLE_IN).split() == SAMPLE_OUT.split()
root = Path(__file__).parent / "data"
for index, content in enumerate(CASES):
    (root / f"{index}.in").write_text(content, encoding="utf-8")
    (root / f"{index}.out").write_text(solve_reference(content), encoding="utf-8")
